/* ========================================
   CreativeHub Design System
   ======================================== */

/* CSS Variables */
:root {
  /* Brand Colors (OKLCH) */
  --brand-primary: oklch(55% 0.22 30);
  --brand-primary-hover: oklch(48% 0.24 30);
  --brand-accent: oklch(65% 0.18 160);
  --brand-accent-hover: oklch(58% 0.2 160);

  /* Neutrals */
  --text-primary: oklch(18% 0.01 280);
  --text-secondary: oklch(45% 0.02 280);
  --text-muted: oklch(60% 0.015 280);
  --bg-surface: oklch(98% 0.005 280);
  --bg-card: oklch(100% 0 0);
  --bg-dark: oklch(20% 0.02 280);
  --border-color: oklch(88% 0.01 280);

  /* Spacing Scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'DM Sans', var(--font-sans);
  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;

  /* Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 oklch(0% 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.1), 0 2px 4px -2px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.1), 0 4px 6px -4px oklch(0% 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.1), 0 8px 10px -6px oklch(0% 0 0 / 0.1);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Container */
  --container-max: 1280px;
  --container-padding: 1.5rem;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-surface);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Utility Classes */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding-left: var(--container-padding);
  padding-right: var(--container-padding);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ========================================
   Header
   ======================================== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--bg-card);
  border-bottom: 1px solid var(--border-color);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: var(--space-4);
}

.logo {
  font-family: var(--font-display);
  font-size: var(--text-xl);
  font-weight: 800;
  color: var(--brand-primary);
  letter-spacing: -0.02em;
  flex-shrink: 0;
}

.nav-desktop {
  display: none;
  align-items: center;
  gap: var(--space-6);
}

.nav-link {
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.nav-link:hover {
  color: var(--text-primary);
}

.nav-link.active {
  color: var(--brand-primary);
  font-weight: 600;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.search-btn {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  font-size: var(--text-sm);
  color: var(--text-muted);
  transition: border-color var(--transition-fast);
}

.search-btn:hover {
  border-color: var(--text-secondary);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-lg);
  font-size: var(--text-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-sm {
  padding: var(--space-1) var(--space-3);
  font-size: var(--text-xs);
}

.btn-primary {
  background: var(--brand-primary);
  color: white;
}

.btn-primary:hover {
  background: var(--brand-primary-hover);
}

.btn-outline {
  border: 1px solid var(--border-color);
  color: var(--text-primary);
}

.btn-outline:hover {
  border-color: var(--text-secondary);
  background: oklch(95% 0.01 280);
}

.btn-accent {
  background: var(--brand-accent);
  color: white;
}

.btn-accent:hover {
  background: var(--brand-accent-hover);
}

.mobile-menu-btn {
  display: flex;
  padding: var(--space-2);
}

/* ========================================
   Promo Banner
   ======================================== */
.promo-banner {
  background: var(--brand-primary);
  color: white;
  position: relative;
  overflow: hidden;
}

.promo-banner.hidden {
  display: none;
}

.promo-banner-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-sm);
  font-weight: 500;
  text-align: center;
}

.promo-banner strong {
  font-weight: 700;
}

.countdown {
  display: inline-flex;
  gap: var(--space-1);
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.countdown-sep {
  opacity: 0.7;
}

.promo-close {
  position: absolute;
  right: var(--space-4);
  top: 50%;
  transform: translateY(-50%);
  color: white;
  opacity: 0.8;
  transition: opacity var(--transition-fast);
  padding: var(--space-1);
}

.promo-close:hover {
  opacity: 1;
}

/* ========================================
   Hero Carousel
   ======================================== */
.hero-section {
  padding: var(--space-12) 0;
  background: linear-gradient(180deg, var(--bg-surface) 0%, oklch(95% 0.01 280) 100%);
  overflow: hidden;
}

.hero-carousel {
  position: relative;
}

.hero-slide {
  display: none;
  grid-template-columns: 1fr;
  gap: var(--space-8);
  align-items: center;
}

.hero-slide.active {
  display: grid;
}

.hero-content {
  max-width: 560px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-3);
  background: oklch(95% 0.05 30);
  color: var(--brand-primary);
  border-radius: var(--radius-xl);
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-4);
}

.hero-title {
  font-family: var(--font-display);
  font-size: var(--text-3xl);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-4);
}

.hero-desc {
  font-size: var(--text-lg);
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: var(--space-6);
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-6);
  flex-wrap: wrap;
}

.hero-meta-item {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-sm);
  color: var(--text-secondary);
}

.hero-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}

.price-sale {
  font-family: var(--font-display);
  font-size: var(--text-3xl);
  font-weight: 800;
  color: var(--brand-primary);
}

.price-original {
  font-size: var(--text-lg);
  color: var(--text-muted);
  text-decoration: line-through;
}

.price-badge {
  padding: var(--space-1) var(--space-2);
  background: oklch(95% 0.05 30);
  color: var(--brand-primary);
  border-radius: var(--radius-sm);
  font-size: var(--text-xs);
  font-weight: 700;
}

.hero-actions {
  display: flex;
  gap: var(--space-3);
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
  border-radius: var(--radius-2xl);
  overflow: hidden;
  aspect-ratio: 16/10;
  background: oklch(90% 0.02 280);
}

.hero-visual img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-visual-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(20% 0.1 30 / 0.3) 0%, transparent 60%);
}

/* Carousel Controls */
.carousel-nav {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-top: var(--space-8);
}

.carousel-arrow {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--border-color);
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  transition: all var(--transition-fast);
  flex-shrink: 0;
}

.carousel-arrow:hover {
  border-color: var(--text-secondary);
  background: oklch(95% 0.01 280);
}

.carousel-arrow:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border-color);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--brand-primary);
  width: 24px;
  border-radius: 4px;
}

/* ========================================
   Section Headers
   ======================================== */
.section {
  padding: var(--space-16) 0;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--space-4);
  margin-bottom: var(--space-8);
  flex-wrap: wrap;
}

.section-title {
  font-family: var(--font-display);
  font-size: var(--text-2xl);
  font-weight: 700;
  letter-spacing: -0.01em;
}

.section-link {
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--brand-primary);
  display: flex;
  align-items: center;
  gap: var(--space-1);
  transition: gap var(--transition-fast);
}

.section-link:hover {
  gap: var(--space-2);
}

/* ========================================
   Course Cards
   ======================================== */
.course-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: var(--space-5);
}

.course-card {
  background: var(--bg-card);
  border-radius: var(--radius-xl);
  overflow: hidden;
  border: 1px solid var(--border-color);
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.course-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.course-thumb {
  position: relative;
  aspect-ratio: 16/10;
  overflow: hidden;
  background: oklch(90% 0.02 280);
}

.course-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.course-card:hover .course-thumb img {
  transform: scale(1.03);
}

.course-badge {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.course-badge--bestseller {
  background: oklch(55% 0.18 100);
  color: white;
}

.course-badge--discount {
  background: var(--brand-primary);
  color: white;
}

.course-badge--free {
  background: var(--brand-accent);
  color: white;
}

.course-info {
  padding: var(--space-4);
}

.course-title {
  font-size: var(--text-base);
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--space-2);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-instructor {
  font-size: var(--text-sm);
  color: var(--text-muted);
  margin-bottom: var(--space-3);
}

.course-stats {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: var(--text-xs);
  color: var(--text-secondary);
  margin-bottom: var(--space-3);
}

.course-stat {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.course-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
}

.course-price-current {
  font-family: var(--font-display);
  font-size: var(--text-lg);
  font-weight: 700;
  color: var(--brand-primary);
}

.course-price-original {
  font-size: var(--text-sm);
  color: var(--text-muted);
  text-decoration: line-through;
}

/* ========================================
   Carousel Track (horizontal scrolling)
   ======================================== */
.carousel-track-wrapper {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: var(--space-5);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: var(--space-2) 0;
  margin: 0 calc(var(--container-padding) * -1);
  padding-left: var(--container-padding);
  padding-right: var(--container-padding);
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-track .course-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
}

.carousel-track-nav {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-2);
  margin-bottom: var(--space-4);
}

/* ========================================
   Value Propositions
   ======================================== */
.value-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
}

.value-card {
  display: flex;
  gap: var(--space-4);
  padding: var(--space-5);
  background: var(--bg-card);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border-color);
  transition: box-shadow var(--transition-base);
}

.value-card:hover {
  box-shadow: var(--shadow-md);
}

.value-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-lg);
  background: oklch(95% 0.05 160);
  color: var(--brand-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.value-content h3 {
  font-size: var(--text-base);
  font-weight: 600;
  margin-bottom: var(--space-1);
}

.value-content p {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ========================================
   Footer
   ======================================== */
.footer {
  background: var(--bg-dark);
  color: oklch(80% 0.02 280);
  padding-top: var(--space-16);
  padding-bottom: var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-8);
  margin-bottom: var(--space-12);
}

.footer-brand {
  max-width: 280px;
}

.footer-logo {
  font-family: var(--font-display);
  font-size: var(--text-xl);
  font-weight: 800;
  color: white;
  margin-bottom: var(--space-4);
}

.footer-desc {
  font-size: var(--text-sm);
  line-height: 1.6;
  color: oklch(70% 0.02 280);
}

.footer-group {
  border-bottom: 1px solid oklch(30% 0.02 280);
}

.footer-group:last-child {
  border-bottom: none;
}

.footer-heading {
  font-size: var(--text-sm);
  font-weight: 600;
  color: white;
  padding: var(--space-4) 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  transition: color var(--transition-fast);
}

.footer-heading:hover {
  color: oklch(90% 0.02 280);
}

.footer-heading-icon {
  transition: transform var(--transition-fast);
}

.footer-group.open .footer-heading-icon {
  transform: rotate(180deg);
}

.footer-links {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.footer-group.open .footer-links {
  max-height: 600px;
}

.footer-links-inner {
  padding-bottom: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.footer-link {
  font-size: var(--text-sm);
  color: oklch(70% 0.02 280);
  transition: color var(--transition-fast);
}

.footer-link:hover {
  color: white;
}

.footer-bottom {
  border-top: 1px solid oklch(30% 0.02 280);
  padding-top: var(--space-8);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  align-items: center;
}

.footer-legal {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--space-4);
  font-size: var(--text-xs);
  color: oklch(60% 0.02 280);
}

.footer-legal a:hover {
  color: oklch(80% 0.02 280);
}

.footer-lang {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--space-3);
  font-size: var(--text-xs);
}

.footer-lang a {
  color: oklch(60% 0.02 280);
  transition: color var(--transition-fast);
}

.footer-lang a:hover {
  color: oklch(80% 0.02 280);
}

/* ========================================
   Courses Page
   ======================================== */
.courses-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-8);
  padding: var(--space-8) 0;
}

.sidebar {
  background: var(--bg-card);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border-color);
  padding: var(--space-5);
  height: fit-content;
}

.sidebar-title {
  font-size: var(--text-lg);
  font-weight: 700;
  margin-bottom: var(--space-4);
}

.sidebar-group {
  margin-bottom: var(--space-5);
}

.sidebar-group-title {
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: var(--space-3);
}

.sidebar-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.sidebar-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  font-size: var(--text-sm);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.sidebar-item:hover {
  background: oklch(95% 0.01 280);
  color: var(--text-primary);
}

.sidebar-item.active {
  background: oklch(95% 0.05 30);
  color: var(--brand-primary);
  font-weight: 600;
}

.sidebar-count {
  font-size: var(--text-xs);
  color: var(--text-muted);
  background: oklch(95% 0.01 280);
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}

.sidebar-item.active .sidebar-count {
  background: oklch(90% 0.05 30);
  color: var(--brand-primary);
}

.courses-main {
  min-width: 0;
}

.category-section {
  margin-bottom: var(--space-12);
}

.category-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-5);
}

.category-title {
  font-family: var(--font-display);
  font-size: var(--text-xl);
  font-weight: 700;
}

.category-courses {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: var(--space-5);
}

/* ========================================
   Projects Page
   ======================================== */
.projects-header {
  padding: var(--space-8) 0;
  background: linear-gradient(180deg, oklch(95% 0.01 280) 0%, var(--bg-surface) 100%);
}

.projects-title {
  font-family: var(--font-display);
  font-size: var(--text-3xl);
  font-weight: 800;
  margin-bottom: var(--space-4);
}

.projects-subtitle {
  font-size: var(--text-lg);
  color: var(--text-secondary);
